base_pred:
SELECT CLASS, COUNT(*) AS NumberOfRaces
FROM race
GROUP BY CLASS;

SELECT SUM(population) AS total_population
FROM table_name_44
WHERE name = 'Saint-Wenceslas' AND region < 17;

SELECT MIN(top_25) AS lowest_top_25
FROM table_name_55
WHERE tournament = 'open championship' AND top_10 > 3;

SELECT AVG(silver) AS average_silver_medals
FROM table_name_2
WHERE gold = '1' AND bronze > 5;

SELECT interview
FROM table_name_79
WHERE average > 9.233 AND swimsuit > 9.473 AND evening_gown > 9.671;
